scripts.世景良.txt:
//和世景良对话
	
	If ($Event << 304) @Event300;
	If ($Event == 304) @Event304;
	If ($Event == 305) @Event304;
	If ($Event >> 305) @Event300;
	
@Event304:
	Say("中年人：请不要来打扰我，有事的话找老板。");
	Return;

@Event300:
	If ($Sub >= 150) @Sub150;
	
	Say("中年人：请不要来打扰我，有事的话找老板。");
	Return;
	
@Sub150:
	If ($Talkshijingliang == 0) @Talk0;
	If ($Talkshijingliang == 1) @Talk1;
	
@Talk0:
	Say("世景良：“西山东月起晚钟，云盘峰顶雾朝松。指点英雄一二事，……”这，这尾句却是什么呢？", 90);
	Say("世景良：西山东月起晚钟，云盘峰顶雾朝松。……", 90);
	
	Choose("独孤剑：这首诗好耳熟……", "A 上前解答", "B 充耳不闻", $Choose);
	If ($Choose == 0) @Choose0;
	If ($Choose == 1) @Choose1;
	
  @Choose0:
	Say("独孤剑：这最后一句乃是：乾坤倒转半枰中。", 1);
	Say("世景良：这位兄台如何得知？", 90);
	Say("独孤剑：在下乃是在武夷山一处秘洞中所见。", 1);
	Say("世景良：哦——“指点英雄一二事，乾坤倒转半枰中。”原来如此，原来如此。", 90);
	Say("独孤剑：请问，这诗中可有什么关窍？", 8);
	Say("世景良：兄台有所不知，这首诗乃是暗示一套武林奇兵的收藏之处。这套奇兵据说是先唐名将南霁云所有，是武林中人梦寐以求的宝贝啊。", 90);
	Say("独孤剑：原来如此。", 1);
	Say("世景良：唉，不过知道了这首诗也没用。这首诗只是谜面的一半，谜面的另一半，传言记载在一份药方之上。", 90);
	Say("独孤剑：一份药方——", 6);
	Say("世景良：不错！所以没有药方，知道这首诗，也终是无用。唉，可惜，可惜啊……", 90);
	Assign($Talkshijingliang, 1);
	Assign($Sub, 160);
	Return;
	
  @Choose1:
	Say("独孤剑：……", 1);
	Say("世景良：这最后的尾句却是什么呢？", 90);
	Return;
	
@Talk1:
	Say("世景良：<enter>西山东月起晚钟，云盘峰顶雾朝松。<enter>指点英雄一二事，乾坤倒转半枰中……", 90);
	Return;

scripts.姚公子对话.txt:
// 与姚公子的同伴对话

	If ($Event == 307) @Event307;
	Return;
	
@Event307:
	Say("独孤剑：如果你以后再敢鱼肉百姓，我可饶不了你！", 5);
	Say("姚公子：不敢，不敢，我再也不敢啦……", 71);
	Return;

scripts.张琳心对话.txt:
// 与张琳心的同伴对话

	If ($Event == 300) @Event300;
	If ($Event == 301) @Event301;
	If ($Event == 307) @Event307;
	If ($Event == 360) @Event360;
	
	Return;
	
@Event300:
	Say("张琳心：咱们四处问问，看看有什么李三的消息。", 21);
	Return;

@Event301:
	Say("张琳心：怎样才能救李三呢？", 21);
	Return;
	
@Event307:
	Say("张琳心：我们快去大牢救李三吧。", 21);
	Return;	
	
@Event360:
	Say("张琳心：我们快去找那个华山派弟子吧。", 21);
	Say("独孤剑：他下山的时候说去妓院，此刻可能还在那里。", 1);
	Return;

